#!/usr/bin/env python3
import sys, os, csv, json, gzip, io, re
from datetime import datetime, timedelta, timezone, date, time as dtime
from fractions import Fraction
from zoneinfo import ZoneInfo

UTC = timezone.utc
EPOCH = datetime(1970, 1, 1, tzinfo=UTC)


def read_text(path):
    with open(path, 'rb') as f:
        b = f.read()
    if b[:2] == b'\x1f\x8b':
        b = gzip.decompress(b)
    t = b.decode('utf-8')
    if t.startswith('\ufeff'):
        t = t[1:]
    return t


def lines_of(t):
    return [l for l in t.replace('\r\n', '\n').replace('\r', '\n').split('\n') if l.strip() != '']


def local_to_utc(naive, tz, fold=0):
    return naive.replace(tzinfo=tz, fold=fold).astimezone(UTC)


def from_epoch(s):
    return EPOCH + timedelta(seconds=s)


def parse_iso(s):
    s = s.strip()
    if s.endswith('Z'):
        s = s[:-1] + '+00:00'
    d = datetime.fromisoformat(s)
    if d.tzinfo is None:
        d = d.replace(tzinfo=UTC)
    return d.astimezone(UTC)


def parse_site(site, tz, fmt, text):
    out = []  # (id, emp, dir, utc)
    L = lines_of(text)
    if fmt == 'abbr-csv':
        hdr = None
        for l in L:
            row = next(csv.reader([l]))
            row = [c.strip() for c in row]
            if 'Badge' in row and 'Punch' in row:
                hdr = row
                continue
            if hdr is None:
                continue
            r = dict(zip(hdr, row))
            m = re.match(r'(\d+):(\d+):(\d+)\s*([AaPp][Mm])?$', r['Time'])
            h, mi, s = int(m.group(1)), int(m.group(2)), int(m.group(3))
            if m.group(4):
                ap = m.group(4).upper()
                h = h % 12 + (12 if ap == 'PM' else 0)
            mo, da, ye = r['Date'].split('/')
            naive = datetime(int(ye), int(mo), int(da), h, mi, s)
            z = r.get('Zone', '').upper()
            fold = 1 if z.endswith('ST') else 0
            out.append((r['Record'], r['Badge'], r['Punch'].upper(), local_to_utc(naive, tz, fold)))
    elif fmt == 'epoch-jsonl':
        schema = 1
        for l in L:
            o = json.loads(l)
            if 'schema' in o and 'id' not in o and 'punch_id' not in o:
                schema = o['schema']
                continue
            if o.get('heartbeat'):
                continue
            if schema == 2:
                pid, emp, d, ms = o['punch_id'], o['employee'], o['direction'], o['epoch_ms']
                u = from_epoch(int(ms) // 1000)
            else:
                pid, emp, d = o['id'], o['emp'], o['dir']
                if 'ts_ms' in o:
                    u = from_epoch(int(o['ts_ms']) // 1000)
                else:
                    u = from_epoch(int(o['ts']))
            out.append((str(pid), emp, d.upper(), u))
    elif fmt == 'offset-csv':
        rd = csv.reader(L, delimiter=';', quotechar='"')
        hdr = None
        for row in rd:
            if hdr is None:
                hdr = [c.strip() for c in row]
                continue
            r = dict(zip(hdr, row))
            d = 'IN' if r['event'].strip() == 'clock_in' else 'OUT'
            out.append((r['punch_id'], r['employee'], d, parse_iso(r['timestamp'])))
    elif fmt == 'legacy-fixed':
        std = None
        off = None
        for l in L:
            c = l[0]
            if c == 'H':
                tail = l[13:18].strip()
                if re.fullmatch(r'[+-]\d{4}', tail):
                    sg = 1 if tail[0] == '+' else -1
                    off = sg * (int(tail[1:3]) * 60 + int(tail[3:5]))
                else:
                    off = None
            elif c == 'D':
                pid = l[1:9]
                badge = l[9:15].strip()
                d = 'IN' if l[15] == 'I' else 'OUT'
                n = datetime.strptime(l[16:30], '%Y%m%d%H%M%S')
                if off is None:
                    # site standard offset
                    probe = n.replace(tzinfo=UTC)
                    cand = None
                    for dd in (0, 1):
                        pass
                    jan = datetime(n.year, 1, 1, tzinfo=tz).utcoffset()
                    jul = datetime(n.year, 7, 1, tzinfo=tz).utcoffset()
                    stdoff = min(jan, jul)
                    # verify via dst() near the date
                    t0 = datetime(n.year, n.month, n.day, 12, tzinfo=tz)
                    stdoff = t0.utcoffset() - (t0.dst() or timedelta(0))
                    u = (n - stdoff).replace(tzinfo=UTC)
                else:
                    u = (n - timedelta(minutes=off)).replace(tzinfo=UTC)
                out.append((pid, 'E' + badge, d, u))
    elif fmt == 'de-tsv':
        hdr = None
        for l in L:
            row = l.split('\t')
            if hdr is None:
                hdr = [c.strip() for c in row]
                continue
            r = dict(zip(hdr, row))
            d = 'IN' if r['Buchung'].strip() == 'K' else 'OUT'
            dd, mm, yy = r['Datum'].strip().split('.')
            hh, mi = r['Uhrzeit'].strip().split(':')[:2]
            naive = datetime(int(yy), int(mm), int(dd), int(hh), int(mi))
            fold = 0 if r['Zeitzone'].strip().upper() == 'MESZ' else 1
            out.append((r['Nr'].strip(), r['Ausweis'].strip(), d, local_to_utc(naive, tz, fold)))
    elif fmt == 'local-csv':
        rd = csv.reader(L)
        hdr = None
        for row in rd:
            if hdr is None:
                hdr = [c.strip() for c in row]
                continue
            r = dict(zip(hdr, row))
            naive = datetime.strptime(r['local_time'].strip(), '%Y-%m-%d %H:%M:%S')
            out.append((r['punch_ref'].strip(), r['employee_id'].strip(), r['direction'].strip().upper(),
                        local_to_utc(naive, tz, 0)))
    elif fmt == 'local-jsonl':
        for l in L:
            o = json.loads(l)
            p = o.get('punch')
            if not p:
                continue
            naive = datetime.strptime(p['at'].strip(), '%Y-%m-%d %H:%M:%S')
            out.append((str(p['id']), p['badge'], p['type'].upper(), local_to_utc(naive, tz, 0)))
    else:
        raise ValueError('unknown format ' + fmt)
    return out


def walk(d):
    for r, _, fs in os.walk(d):
        for f in sorted(fs):
            yield os.path.join(r, f)


def round_punch(u, tz):
    off = u.astimezone(tz).utcoffset()
    secs = int((u - EPOCH).total_seconds()) + int(off.total_seconds())
    r = ((secs + 180) // 360) * 360
    return u + timedelta(seconds=r - secs)


def money(fr):
    c = fr * 100
    return int((c + Fraction(1, 2)) // 1)


def fmt_money(c):
    return '%d.%02d' % (c // 100, c % 100)


def main(inp, outp):
    period = json.load(open(os.path.join(inp, 'period.json')))
    pstart = date.fromisoformat(period['start'])
    pend = date.fromisoformat(period['end'])
    cutoff = parse_iso(period['corrections_cutoff'])
    sites = {}
    with open(os.path.join(inp, 'sites.csv'), encoding='utf-8-sig', newline='') as f:
        for r in csv.DictReader(f):
            sites[r['site'].strip()] = (ZoneInfo(r['timezone'].strip()), r['format'].strip())
    emps = {}
    with open(os.path.join(inp, 'employees.csv'), encoding='utf-8-sig', newline='') as f:
        for r in csv.DictReader(f):
            emps[r['employee_id'].strip()] = r['home_site'].strip()
    rates = {}
    with open(os.path.join(inp, 'rates.csv'), encoding='utf-8-sig', newline='') as f:
        for r in csv.DictReader(f):
            rates.setdefault(r['employee_id'].strip(), []).append(
                (date.fromisoformat(r['effective_from'].strip()), Fraction(r['hourly_rate'].strip())))
    for v in rates.values():
        v.sort()

    punches = {}  # (site,id) -> [emp, dir, utc]
    ever = set()
    for site, (tz, fmt) in sites.items():
        d = os.path.join(inp, 'exports', site)
        if not os.path.isdir(d):
            continue
        for p in walk(d):
            for pid, emp, dr, u in parse_site(site, tz, fmt, read_text(p)):
                k = (site, str(pid))
                ever.add(k)
                punches[k] = [emp, dr, u]

    corr = []
    cd = os.path.join(inp, 'corrections')
    if os.path.isdir(cd):
        for p in walk(cd):
            t = read_text(p)
            for r in csv.DictReader(io.StringIO(t)):
                r = {k.strip(): (v or '').strip() for k, v in r.items() if k}
                if not r.get('correction_id'):
                    continue
                corr.append(r)
    corr = [(parse_iso(r['issued_at']), r['correction_id'], r) for r in corr]
    corr = [c for c in corr if c[0] <= cutoff]
    corr.sort(key=lambda c: (c[0], c[1]))
    applied = 0
    for _, _, r in corr:
        k = (r['site'], r['punch_id'])
        a = r['action']
        if a == 'void':
            if k in punches:
                del punches[k]
                applied += 1
        elif a == 'set':
            if k in punches:
                punches[k][2] = parse_iso(r['time'])
                applied += 1
        elif a == 'add':
            if k not in ever:
                ever.add(k)
                punches[k] = [r['employee'], r['type'].upper(), parse_iso(r['time'])]
                applied += 1

    by_emp = {}
    for (site, pid), (emp, dr, u) in punches.items():
        if emp in emps:
            by_emp.setdefault(emp, []).append((u, 0 if dr == 'OUT' else 1, site, pid, dr))

    res = {e: dict(shifts=0, paid_minutes=0, overtime_minutes=0, night_minutes=0, cents=Fraction(0)) for e in emps}
    exc = dict(open_shifts=0, orphan_outs=0, duplicates_dropped=0)

    for emp, lst in by_emp.items():
        home = sites[emps[emp]][0]
        lst.sort(key=lambda x: (x[0], x[1], x[2], x[3]))

        def rnd(x):
            return round_punch(x[0], sites[x[2]][0])

        def wd(r):
            return r.astimezone(home).date()
        kept = []
        for x in lst:
            if kept and kept[-1][4] == x[4] and (x[0] - kept[-1][0]).total_seconds() <= 300:
                if pstart <= wd(rnd(x)) <= pend:
                    exc['duplicates_dropped'] += 1
                continue
            kept.append(x)
        shifts = []
        pending = None
        for x in kept:
            r = rnd(x)
            if x[4] == 'IN':
                if pending is not None:
                    if pstart <= wd(pending[1]) <= pend:
                        exc['open_shifts'] += 1
                pending = (x, r)
            else:
                if pending is not None and (r - pending[1]) <= timedelta(hours=16):
                    shifts.append((pending, (x, r)))
                    pending = None
                else:
                    if pending is not None:
                        if pstart <= wd(pending[1]) <= pend:
                            exc['open_shifts'] += 1
                        pending = None
                    if pstart <= wd(r) <= pend:
                        exc['orphan_outs'] += 1
        if pending is not None and pstart <= wd(pending[1]) <= pend:
            exc['open_shifts'] += 1
        # shifts
        rows = []
        for (ix, ri), (ox, ro) in shifts:
            w = wd(ri)
            if not (pstart <= w <= pend):
                continue
            worked = max(0, int((ro - ri).total_seconds() // 60))
            paid = worked - 30 if worked > 360 else worked
            tz = sites[ix[2]][0]
            night = 0
            l0 = ri.astimezone(tz).date() - timedelta(days=1)
            l1 = ro.astimezone(tz).date() + timedelta(days=1)
            dd = l0
            while dd <= l1:
                nx = dd + timedelta(days=1)
                for a, b in ((dtime(0), dtime(6)), (dtime(22), None)):
                    s = local_to_utc(datetime.combine(dd, a), tz)
                    e = local_to_utc(datetime.combine(dd, b) if b else datetime.combine(nx, dtime(0)), tz)
                    lo, hi = max(s, ri), min(e, ro)
                    if hi > lo:
                        night += int((hi - lo).total_seconds()) // 60
                dd = nx
            night = min(night, paid)
            rows.append([ri, w, paid, night])
        rows.sort(key=lambda r: r[0])
        daily = {}
        weekly = {}
        rl = rates.get(emp, [])
        R = res[emp]
        for ri, w, paid, night in rows:
            used = daily.get(w, 0)
            dot = max(0, used + paid - 480) - max(0, used - 480)
            daily[w] = used + paid
            nd = paid - dot
            wk = w - timedelta(days=w.weekday())
            wu = weekly.get(wk, 0)
            wot = max(0, wu + nd - 2400) - max(0, wu - 2400)
            weekly[wk] = wu + nd
            ot = dot + wot
            reg = paid - ot
            rate = Fraction(0)
            for ef, rt in rl:
                if ef <= w:
                    rate = rt
            R['cents'] += rate * (reg + Fraction(3, 2) * ot) / 60 + rate * Fraction(15, 100) * night / 60
            R['shifts'] += 1
            R['paid_minutes'] += paid
            R['overtime_minutes'] += ot
            R['night_minutes'] += night

    out = {'period': {'start': period['start'], 'end': period['end']}, 'employees': {}}
    tot = dict(shifts=0, paid_minutes=0, overtime_minutes=0, night_minutes=0)
    tg = 0
    for e, R in res.items():
        g = money(R['cents'])
        out['employees'][e] = {k: R[k] for k in tot}
        out['employees'][e]['gross'] = fmt_money(g)
        for k in tot:
            tot[k] += R[k]
        tg += g
    exc['corrections_applied'] = applied
    out['exceptions'] = exc
    tot['gross'] = fmt_money(tg)
    out['totals'] = tot
    with open(outp, 'w') as f:
        json.dump(out, f, indent=1)


if __name__ == '__main__':
    main(sys.argv[1], sys.argv[2])
